helpers.cm_acos:
def cm_acos(a)
  (a >= -1.0 && a <= 1.0) ? Math.acos(a) : Float::NAN
end

helpers.cm_asin:
def cm_asin(a)
  (a >= -1.0 && a <= 1.0) ? Math.asin(a) : Float::NAN
end

helpers.cm_fmod:
def cm_fmod(a, b)
  b != 0.0 ? a.remainder(b) : Float::NAN
end

helpers.cm_fsqrt:
def cm_fsqrt(a)
  a >= 0.0 ? Math.sqrt(a) : Float::NAN
end

helpers.cm_max_f:
def cm_max_f(a, b)
  b > a ? b : a
end

helpers.cm_max_i:
def cm_max_i(a, b)
  b > a ? b : a
end

helpers.cm_min_f:
def cm_min_f(a, b)
  b < a ? b : a
end

helpers.cm_min_i:
def cm_min_i(a, b)
  b < a ? b : a
end

helpers.cm_print_list:
def cm_print_list(xs, tag)
  puts('l:' + xs.length.to_s)
  xs.each { |v| puts(tag + ':' + v.to_s) }
end

helpers.cm_s_cmp:
def cm_s_cmp(a, b)
  a.codepoints <=> b.codepoints
end
